      tgt.style.setProperty('--gx', (r1 * 6).toFixed(2) + 'em'); tgt.style.setProperty('--gy', (r2 * 4).toFixed(2) + 'em'); tgt.style.setProperty('--gr', (r1 * 360).toFixed(0) + 'deg');
